fn capitalize_first_letter(mut word: Vec<char>) -> Vec<char> {
    // The problem guarantees `word` is non-empty, so it's safe to index [0].
    // If the first character isn't an ASCII uppercase letter, replace it with 'A'.
    if !word[0].is_ascii_uppercase() {
        word[0] = 'A';
    }
    // Return the modified vector.
    word
}

